```javascript
// Assume you have an array of products with their inventory levels
const products = [
  { name: 'Product A', inventory: 10 },
  { name: 'Product B', inventory: 5 },
  { name: 'Product C', inventory: 15 }
];

// Set the threshold for low inventory
const lowInventoryThreshold = 5;

// Function to check if a product's inventory is low
function isLowInventory(product) {
  return product.inventory <= lowInventoryThreshold;
}

// Function to send a notification when a product's inventory is low
function notifyInventoryManager(product) {
  // Send a notification to the inventory manager using a service like EmailJS or Pusher
  console.log(`Product ${product.name} is low in inventory.`);
}

// Check inventory levels and send notifications
