import { Model, Schema } from 'mongoose';
import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongodb';

export interface UserSchema {
  name: string;
  age: number;
}

export interface AddressSchema {
  street: string;
  city: string;
  state: string;
}

const userSchema = new Schema({
  name: { type: String, required: true },
  age: { type: Number, required: true },
});

const addressSchema = new Schema({
  street: { type: String, required: true },
  city: { type: String, required: true },
  state: { type: String, required: true },
});

@Injectable()
export class UserModel {
  constructor(@InjectModel('User') private readonly userModel: Model) {}

  async createUser(user: UserSchema, address: AddressSchema): Promise<any> {
    const createdUser = new this.userModel({ ...user });
    createdUser.address = new this.addressModel({ ...address });

    try {
      const result = await createdUser.save();
      return result;
    } catch (error) {
      throw error;
    }
  }
}
```
