Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getEntriesByKey(object, key) {
  const entries = [];

  function traverseObject(obj, path) {
    for (const key in obj) {
      if (path === key) {
        entries.push(obj[key]);
      } else {
        traverseObject(obj[key], path);
      }
    }
  }

  traverseObject(object, key);
  return entries;
}

// Example usage
const object = {
  a: {
    b: 1,
    c: 2,
  },
  b: {
    d: 3,
    e: 4,
  },
};

const key = 'b';
const entries = getEntriesByKey(object, key);
console.log(entries); // Output: [3, 4]
```

