Here's a simple Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"
)

type StructDefinition struct {
	Name     string
	Fields   []FieldDefinition
}

type FieldDefinition struct {
	Name    string
	Type    string
	Default string
}

func parseStruct(filePath string, structName string) (StructDefinition, error) {
	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		return StructDefinition{}, fmt.Errorf("error reading file: %w", err)
	}

	re := regexp.MustCompile(`(?m)^type\s+(\w+)\s+struct \{`)
	matches := re.FindAllString(string(content), -1)

	if len(matches) == 0 {
		return StructDefinition{}, fmt.Errorf("no struct found in file")
	}

	structDef := StructDefinition{
		Name:     matches[0],
		Fields:   make([]FieldDefinition, 0),
	}

	for _, match := range matches {
		fields := re.FindAllString(match, -1)

		for _, field := range fields {
			fieldMatch := regexp.MustCompile(`^(\w+)\s+(\w+)\s*(?:\s*default\s+("(?:\\"|[^"])+"))?$`)
			fieldMatchResult := fieldMatch.FindStringSubmatch(field)

			if len(fieldMatchResult) == 3 {
				fieldDef := FieldDefinition{
					Name:    fieldMatchResult[1],
					Type:    fieldMatchResult[2],
					Default: fieldMatchResult[3],
				}

