```csharp
using UnityEngine;
using System.Collections;
using Unity.Audio;

public class AudioVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public GameObject visualizerObject;

    private float amplitude;
    private float frequency;

    void Start()
    {
        audioSource = GetComponent<AudioSource>();
        visualizerObject = transform.Find("Visualizer").gameObject;
    }

    void Update()
    {
        amplitude = audioSource.volume * 0.5f;
        frequency = audioSource.pitch * 2f;

        visualizerObject.transform.localScale = new Vector3(amplitude, amplitude, amplitude);
        visualizerObject.transform.localRotation = Quaternion.Euler(0f, 0f, frequency);
    }
}
```

