To create a simple toast notification using React Context, follow these steps:

1. Create a `ToastContext` component that will serve as the context provider:

```javascript
import { createContext, useState } from 'react';

const ToastContext = createContext({});

function ToastProvider(props) {
  const [toasts, setToasts] = useState([]);

  const addToast = (message, type) => {
    setToasts((prevToasts) => [...prevToasts, { message, type }]);
  };

  return (
    <ToastContext.Provider value={{ toasts, addToast }}>
      {props.children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. In your main application component, wrap your content in the `ToastProvider`:

```javascript
import React from 'react';
import { ToastContext, ToastProvider } from './ToastContext';

function App() {
  return (
    <ToastProvider>
      {/* Your app content goes here */}
    </ToastProvider>
  );
}

export default App;
```

