    setEmails(filteredEmails);
  };

  return (
    <div {...getComboboxProps()}>
      <input
        {...getInputProps({
          placeholder: 'Search emails',
          value: searchTerm,
          onChange: handleInputChange,
        })}
      />
      {isOpen ? (
        <ul {...getMenuProps()}>
          {emails.map((email) => (
            <li key={email} onClick={() => handleSelect(email)}>{email}</li>
          ))}
        </ul>
      ) : null}
    </div>
  );
};

export default EmailsInput;
