class RedisClient {
  constructor(host, port, password) {
    this.client = require('redis').createClient({
      host,
      port,
      password,
      retry_strategy: () => 1000, // Retry after 1 second if the connection is lost
    });

    this.client.on('error', (err) => {
      console.error('Redis error:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      return false;
    }
  }

  async get(key) {
    const value = await this.client.get(key);
    return value;
  }

  async set(key, value, duration) {
    await this.client.setex(key, duration, value);
  }

  async del(key) {
    await this.client.del(key);
  }
}

const redisClient = new RedisClient('localhost', 6379, 'your_password');
module.exports = redisClient;
```

Replace `'your_password'` with your Redis password.

