```powershell
# Get the list of all users and groups in the domain
$usersAndGroups = (Get-ADUser -Filter {(objectCategory -eq "person")} -Properties *).DistinguishedName

# Define a function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSidInSidHistory($sid) {
    foreach ($userOrGroup in $usersAndGroups) {
        $sidHistory = (Get-ADUser -Identity $userOrGroup -Properties sidHistory).SidHistory
        if ($sidHistory -contains $sid) {
            return $true
        }
    }
    return $false
}

# Recursively check the ACLs of each folder for SIDs that occur only in the SIDHistory of any user or group in the domain
function CheckFolderAcls($folderPath) {
    $acl = (Get-Acl -Path $folderPath).Access
    foreach ($access in $acl) {
        if ($access.IdentityReference -match '^S-1-5-21-') {
            $sid = New-Object System.Security.Principal.SecurityIdentifier($access.IdentityReference)
            if (CheckSidInSidHistory($sid.Value)) {
                Write-Host "The ACL of $folderPath contains a SID ($sid.Value) that occurs only in the SIDHistory of a user or group in the domain."
            }
        }
    }
    foreach ($subFolder in (Get-ChildItem -Path $folderPath -Directory)) {
        CheckFolderAcls($subFolder.FullName)
    }
}

# Start the recursive check
CheckFolderAcls("C:\path\to\root\folder")
```

Replace `"C:\path\to\root\folder"` with the root folder you want to start the recursive check from.
